-- Index gabungan: urutan kolom = urutan kondisi di WHERE, lalu ORDER BY
CREATE INDEX idx_products_cat_status_created
  ON products (category_id, status, created_at DESC);

-- Cek index apa saja yang sudah ada di sebuah tabel (MySQL)
SHOW INDEX FROM products;

-- Cek ukuran index (PostgreSQL)
SELECT indexrelname, pg_size_pretty(pg_relation_size(indexrelid))
FROM pg_stat_user_indexes
WHERE relname = 'products';

-- BURUK: N+1 query (1 + 50 query untuk satu halaman)
-- SELECT * FROM products LIMIT 50;
-- lalu untuk tiap produk: SELECT name FROM categories WHERE id = ?;

-- BAIK: satu query dengan JOIN, semua data kembali sekaligus
SELECT p.id, p.name, p.price, c.name AS category_name
FROM products p
JOIN categories c ON c.id = p.category_id
WHERE p.status = 'active'
ORDER BY p.created_at DESC
LIMIT 50;
